package com.tianshu.assets.governance.infrastructure;
import com.fasterxml.jackson.databind.ObjectMapper;import com.tianshu.assets.governance.audit.application.GovernanceAuditStore;import com.tianshu.assets.governance.audit.domain.GovernanceAuditEvent;import java.util.List;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.stereotype.Repository;
@Repository @Profile({"local","oceanbase"}) @ConditionalOnProperty(name="asset.governance-schema-enabled",havingValue="true")
public class JdbcGovernanceAuditStore extends JdbcGovernanceSupport implements GovernanceAuditStore {public JdbcGovernanceAuditStore(JdbcClient j,ObjectMapper o,@Value("${asset.database-writes-enabled:false}")boolean w){super(j,o,w);}@Override public GovernanceAuditEvent append(GovernanceAuditEvent e){requireWritable();var k=new GeneratedKeyHolder();jdbc.sql("INSERT INTO governance_audit_event(task_id,item_id,aggregate_type,aggregate_id,action,governance_round,actor_user_id,before_json,after_json,created_at) VALUES(:task,:item,:type,:aggregate,:action,:round,:actor,:before,:after,:at)").param("task",e.taskId()).param("item",e.itemId()).param("type",e.aggregateType()).param("aggregate",e.aggregateId()).param("action",e.action()).param("round",e.governanceRound()).param("actor",e.actorUserId()).param("before",e.beforeJson()).param("after",e.afterJson()).param("at",e.createdAt()).update(k,"id");return new GovernanceAuditEvent(k.getKeyAs(Long.class),e.taskId(),e.itemId(),e.aggregateType(),e.aggregateId(),e.action(),e.governanceRound(),e.actorUserId(),e.beforeJson(),e.afterJson(),e.createdAt());}@Override public List<GovernanceAuditEvent> history(long task){return jdbc.sql("SELECT id,task_id,item_id,aggregate_type,aggregate_id,action,governance_round,actor_user_id,before_json,after_json,created_at FROM governance_audit_event WHERE task_id=:task ORDER BY created_at,id").param("task",task).query((r,n)->new GovernanceAuditEvent(r.getLong("id"),r.getLong("task_id"),r.getObject("item_id",Long.class),r.getString("aggregate_type"),r.getLong("aggregate_id"),r.getString("action"),r.getInt("governance_round"),r.getString("actor_user_id"),r.getString("before_json"),r.getString("after_json"),r.getTimestamp("created_at").toInstant())).list();}}
